using System.Security.Cryptography;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.Data.SqlClient;
using ShopApi.Data;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ShopDb>();
builder.Services.AddDistributedMemoryCache();
builder.Services.AddSession(o => { o.Cookie.Name = "banhoa.session"; o.Cookie.HttpOnly = true; o.Cookie.SameSite = SameSiteMode.Lax; o.IdleTimeout = TimeSpan.FromHours(8); });
var keys = Path.Combine(builder.Environment.ContentRootPath, ".keys"); Directory.CreateDirectory(keys);
builder.Services.AddDataProtection().PersistKeysToFileSystem(new DirectoryInfo(keys));
builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => { var origin = builder.Configuration["Cors:Origin"] ?? Environment.GetEnvironmentVariable("CORS_ORIGIN"); if (!string.IsNullOrWhiteSpace(origin)) p.WithOrigins(origin).AllowCredentials().AllowAnyHeader().AllowAnyMethod(); }));
var app = builder.Build(); app.UseCors(); app.UseSession(); app.UseSwagger(); app.UseSwaggerUI();
app.Use(async (ctx, next) => { try { await next(); } catch (SqlException ex) { app.Logger.LogError(ex, "SQL Server failure"); ctx.Response.StatusCode = 503; await ctx.Response.WriteAsJsonAsync(new { error = "Không thể truy cập cơ sở dữ liệu SQL Server." }); } catch (Exception ex) { app.Logger.LogError(ex, "API failure"); ctx.Response.StatusCode = 500; await ctx.Response.WriteAsJsonAsync(new { error = "Đã xảy ra lỗi máy chủ." }); } });
app.MapGet("/", () => Results.Redirect("/swagger")).WithSummary("Mở giao diện Swagger."); app.MapGet("/health", () => Results.Ok(new { status = "ok" })).WithSummary("Kiểm tra trạng thái hoạt động của API.");

var auth = app.MapGroup("/api/auth").WithTags("Tài khoản");
auth.MapPost("/register", async (Register r, ShopDb db) =>
{
    if (string.IsNullOrWhiteSpace(r.Username) || r.Username.Trim().Length < 3 || string.IsNullOrWhiteSpace(r.Password) || r.Password.Length < 8 || string.IsNullOrWhiteSpace(r.FullName) || string.IsNullOrWhiteSpace(r.Phone)) return Bad("username/password/profile", "Tên đăng nhập (tối thiểu 3 ký tự), họ tên, số điện thoại và mật khẩu (tối thiểu 8 ký tự) là bắt buộc.");
    await using var cn = await db.OpenAsync();
    await using var tx = (SqlTransaction)await cn.BeginTransactionAsync();
    var username = r.Username.Trim();
    var exists = await Scalar(cn, "SELECT COUNT(1) FROM ACCOUNT WHERE Username=@u", tx, ("@u", username));
    if (Convert.ToInt32(exists) > 0) return Results.Conflict(new { error = "Tên đăng nhập đã được sử dụng." });
    var id = await Scalar(cn, "INSERT INTO ACCOUNT(Username,PasswordHash,Role) OUTPUT INSERTED.AccountID VALUES(@u,@p,N'KhachHang')", tx, ("@u", username), ("@p", Hash(r.Password)));
    var customerId = await Scalar(cn, "INSERT INTO CUSTOMER(FullName,Gender,DateOfBirth,Email,PhoneNumber,Address,AccountID) OUTPUT INSERTED.CustomerID VALUES(@name,@gender,@dob,@email,@phone,@address,@account)", tx, ("@name", r.FullName.Trim()), ("@gender", r.Gender), ("@dob", r.DateOfBirth), ("@email", EmptyToNull(r.Email)), ("@phone", r.Phone.Trim()), ("@address", r.Address), ("@account", id));
    await tx.CommitAsync();
    return Results.Created($"/api/customers/{customerId}", new { accountId = id, customerId, message = "Đăng ký tài khoản khách hàng thành công." });
}).WithTags("Đăng ký khách hàng").WithSummary("Khách vãng lai đăng ký tài khoản khách hàng; không cần đăng nhập trước.");
auth.MapPost("/admin/login", (Login r, HttpContext ctx, ShopDb db) => LoginForRole(r, "QuanTriVien", ctx, db))
    .WithTags("Đăng nhập quản trị").WithSummary("Đăng nhập dành riêng cho trang quản trị; chỉ tài khoản quản trị viên được phép.");
auth.MapPost("/customer/login", (Login r, HttpContext ctx, ShopDb db) => LoginForRole(r, "KhachHang", ctx, db))
    .WithTags("Đăng nhập khách hàng").WithSummary("Đăng nhập dành riêng cho trang khách hàng; chỉ tài khoản khách hàng được phép.");
// Giữ endpoint cũ để các client đang dùng /api/auth/login không bị hỏng.
auth.MapPost("/login", (Login r, HttpContext ctx, ShopDb db) => LoginForRole(r, null, ctx, db))
    .WithSummary("Đăng nhập tương thích cũ; giao diện mới nên dùng endpoint riêng theo vai trò.");
auth.MapPost("/logout", (HttpContext c) => { c.Session.Clear(); return Results.Ok(new { message = "Đã đăng xuất." }); }).WithSummary("Đăng xuất và xóa session hiện tại.");
auth.MapGet("/me", (HttpContext c) => AccountId(c) == 0 ? Results.Unauthorized() : Results.Ok(new { accountId = AccountId(c), customerId = CustomerId(c), username = c.Session.GetString("username"), fullName = c.Session.GetString("fullName"), role = c.Session.GetString("role") })).WithSummary("Lấy thông tin tài khoản đang đăng nhập.");
app.MapPatch("/api/me", async (Profile r, HttpContext c, ShopDb db) =>
{
    if (!IsCustomer(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); await Exec(cn, "UPDATE CUSTOMER SET FullName=@name,PhoneNumber=@phone,Email=@email,Address=@address WHERE CustomerID=@id", null, ("@name", r.FullName), ("@phone", r.Phone), ("@email", EmptyToNull(r.Email)), ("@address", r.Address), ("@id", CustomerId(c)));
    c.Session.SetString("fullName", r.FullName); return Results.Ok(new { message = "Đã cập nhật hồ sơ." });
}).WithTags("Khách hàng").WithSummary("Cập nhật hồ sơ và địa chỉ khách hàng.");

app.MapGet("/api/product-types", async (ShopDb db) => await List(db, "SELECT ProductTypeID id,ProductTypeName name,Description description FROM PRODUCT_TYPE WHERE Status=1 ORDER BY ProductTypeName")).WithTags("Sản phẩm").WithSummary("Liệt kê loại sản phẩm đang hiển thị.");
app.MapGet("/api/products", async (int? typeId, string? q, decimal? minPrice, decimal? maxPrice, int? page, int? pageSize, ShopDb db) =>
{
    if (minPrice < 0 || maxPrice < 0 || minPrice > maxPrice) return Bad("price", "Khoảng giá không hợp lệ."); var p = Math.Max(1, page ?? 1); var take = Math.Clamp(pageSize ?? 20, 1, 100);
    var f = new List<string> { "p.Status=1", "t.Status=1" }; var a = new List<(string, object?)>(); if (typeId.HasValue) { f.Add("p.ProductTypeID=@type"); a.Add(("@type", typeId)); } if (!string.IsNullOrWhiteSpace(q)) { f.Add("(p.ProductName LIKE @q OR p.ProductCode LIKE @q)"); a.Add(("@q", "%" + q.Trim() + "%")); } if (minPrice.HasValue) { f.Add("p.SellingPrice>=@min"); a.Add(("@min", minPrice)); } if (maxPrice.HasValue) { f.Add("p.SellingPrice<=@max"); a.Add(("@max", maxPrice)); }
    var where = string.Join(" AND ", f); await using var cn = await db.OpenAsync(); var total = Convert.ToInt32(await Scalar(cn, $"SELECT COUNT(*) FROM PRODUCT p JOIN PRODUCT_TYPE t ON t.ProductTypeID=p.ProductTypeID WHERE {where}", null, a.ToArray())); var rows = await Rows(cn, $"SELECT p.ProductID id,p.ProductCode code,p.ProductName name,p.Description description,p.Color color,p.Unit unit,p.SellingPrice price,p.StockQuantity stock,p.Image image,t.ProductTypeID typeId,t.ProductTypeName typeName FROM PRODUCT p JOIN PRODUCT_TYPE t ON t.ProductTypeID=p.ProductTypeID WHERE {where} ORDER BY p.ProductName OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY", null, [.. a, ("@skip", (p - 1) * take), ("@take", take)]);
    return Results.Ok(new { items = rows, pagination = new { page = p, pageSize = take, totalItems = total, totalPages = (int)Math.Ceiling(total / (double)take) } });
}).WithTags("Sản phẩm").WithSummary("Tìm theo tên, loại, khoảng giá; có phân trang");
app.MapGet("/api/products/{id:int}", async (int id, ShopDb db) => { await using var cn = await db.OpenAsync(); var row = await One(cn, "SELECT p.*,t.ProductTypeName FROM PRODUCT p JOIN PRODUCT_TYPE t ON t.ProductTypeID=p.ProductTypeID WHERE p.ProductID=@id AND p.Status=1", null, ("@id", id)); return row is null ? Results.NotFound() : Results.Ok(new { item = row }); }).WithTags("Sản phẩm").WithSummary("Xem chi tiết sản phẩm đang được bán.");

var admin = app.MapGroup("/api/admin").WithTags("Quản trị");
admin.MapGet("/products", async (HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT p.ProductID,p.ProductCode,p.ProductName,p.ProductTypeID,t.ProductTypeName,p.Description,p.Color,p.Unit,p.CostPrice,p.ProfitRate,p.SellingPrice,p.StockQuantity,p.MinStockLevel,p.Image,p.SupplierName,p.Status FROM PRODUCT p JOIN PRODUCT_TYPE t ON t.ProductTypeID=p.ProductTypeID ORDER BY p.ProductName")).WithSummary("Quản trị: liệt kê sản phẩm đang bán và sản phẩm đã ẩn.");
admin.MapPost("/users", async (AdminCustomer r, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); if (r.Password.Length < 8 || string.IsNullOrWhiteSpace(r.Username) || string.IsNullOrWhiteSpace(r.FullName) || string.IsNullOrWhiteSpace(r.Phone)) return Bad("customer", "Cần tên đăng nhập, họ tên, số điện thoại và mật khẩu tối thiểu 8 ký tự.");
    await using var cn = await db.OpenAsync(); await using var tx = (SqlTransaction)await cn.BeginTransactionAsync(); var accountId = await Scalar(cn, "INSERT INTO ACCOUNT(Username,PasswordHash,Role) OUTPUT INSERTED.AccountID VALUES(@u,@p,N'KhachHang')", tx, ("@u", r.Username.Trim()), ("@p", Hash(r.Password)));
    var customerId = await Scalar(cn, "INSERT INTO CUSTOMER(FullName,Gender,DateOfBirth,Email,PhoneNumber,Address,AccountID) OUTPUT INSERTED.CustomerID VALUES(@name,@gender,@dob,@email,@phone,@address,@account)", tx, ("@name", r.FullName.Trim()), ("@gender", r.Gender), ("@dob", r.DateOfBirth), ("@email", EmptyToNull(r.Email)), ("@phone", r.Phone.Trim()), ("@address", r.Address), ("@account", accountId)); await tx.CommitAsync(); return Results.Created($"/api/admin/users/{customerId}", new { customerId, accountId });
}).WithSummary("Tạo tài khoản khách hàng và hồ sơ từ trang quản trị.");
admin.MapGet("/product-types", async (HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT ProductTypeID id,ProductTypeName name,Description description,Status status FROM PRODUCT_TYPE ORDER BY ProductTypeName")).WithSummary("Quản trị: liệt kê tất cả loại sản phẩm, gồm cả loại đã ẩn.");
admin.MapPost("/product-types", async (TypeRequest r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var id = await Scalar(cn, "INSERT INTO PRODUCT_TYPE(ProductTypeName,Description) OUTPUT INSERTED.ProductTypeID VALUES(@n,@d)", null, ("@n", r.Name), ("@d", r.Description)); return Results.Created($"/api/admin/product-types/{id}", new { id }); }).WithSummary("Quản trị: tạo loại sản phẩm mới.");
admin.MapPut("/product-types/{id:int}", async (int id, TypeRequest r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE PRODUCT_TYPE SET ProductTypeName=@n,Description=@d WHERE ProductTypeID=@id", null, ("@n", r.Name), ("@d", r.Description), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { message = "Đã cập nhật loại sản phẩm." }); }).WithSummary("Quản trị: sửa tên và mô tả loại sản phẩm.");
admin.MapDelete("/product-types/{id:int}", async (int id, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE PRODUCT_TYPE SET Status=0 WHERE ProductTypeID=@id", null, ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { message = "Đã ẩn loại sản phẩm." }); }).WithSummary("Quản trị: ẩn loại sản phẩm (xóa mềm).");
admin.MapPost("/products", async (ProductCreate r, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); if (r.TypeId <= 0 || r.Quantity < 0 || r.CostPrice < 0 || r.ProfitRate < 0 || string.IsNullOrWhiteSpace(r.Code) || string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Unit)) return Bad("product", "Thông tin sản phẩm không hợp lệ.");
    await using var cn = await db.OpenAsync(); var id = await Scalar(cn, "INSERT INTO PRODUCT(ProductCode,ProductName,ProductTypeID,Description,Color,Unit,CostPrice,ProfitRate,StockQuantity,MinStockLevel,Image,SupplierName,Status) OUTPUT INSERTED.ProductID VALUES(@code,@name,@type,@desc,@color,@unit,@cost,@rate,@qty,@minimum,@image,@supplier,@status)", null, ("@code", r.Code), ("@name", r.Name), ("@type", r.TypeId), ("@desc", r.Description), ("@color", r.Color), ("@unit", r.Unit), ("@cost", r.CostPrice), ("@rate", r.ProfitRate), ("@qty", r.Quantity), ("@minimum", r.MinStockLevel), ("@image", r.Image), ("@supplier", r.SupplierName), ("@status", r.Status)); return Results.Created($"/api/admin/products/{id}", new { id });
}).WithSummary("Tạo sản phẩm mới, gồm mã, giá vốn, giá bán, tồn đầu và trạng thái.");
admin.MapPut("/products/{id:int}", async (int id, ProductUpdate r, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE PRODUCT SET ProductCode=COALESCE(@code,ProductCode),ProductName=COALESCE(@name,ProductName),ProductTypeID=COALESCE(@type,ProductTypeID),Description=COALESCE(@desc,Description),Color=COALESCE(@color,Color),Unit=COALESCE(@unit,Unit),CostPrice=COALESCE(@cost,CostPrice),ProfitRate=COALESCE(@rate,ProfitRate),MinStockLevel=COALESCE(@minimum,MinStockLevel),Image=CASE WHEN @clearImage=1 THEN NULL ELSE COALESCE(@image,Image) END,SupplierName=COALESCE(@supplier,SupplierName),Status=COALESCE(@status,Status) WHERE ProductID=@id", null, ("@code", r.Code), ("@name", r.Name), ("@type", r.TypeId), ("@desc", r.Description), ("@color", r.Color), ("@unit", r.Unit), ("@cost", r.CostPrice), ("@rate", r.ProfitRate), ("@minimum", r.MinStockLevel), ("@image", r.Image), ("@clearImage", r.ClearImage), ("@supplier", r.SupplierName), ("@status", r.Status), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { message = "Đã cập nhật sản phẩm." });
}).WithSummary("Cập nhật thông tin sản phẩm; dùng clearImage=true để bỏ ảnh.");
admin.MapDelete("/products/{id:int}", async (int id, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); await using var tx = (SqlTransaction)await cn.BeginTransactionAsync(); var refs = Convert.ToInt32(await Scalar(cn, "SELECT (SELECT COUNT(*) FROM GOODS_RECEIPT_DETAIL WHERE ProductID=@id)+(SELECT COUNT(*) FROM ORDER_DETAIL WHERE ProductID=@id)", tx, ("@id", id)));
    if (refs == 0) { await Exec(cn, "DELETE FROM PRODUCT WHERE ProductID=@id", tx, ("@id", id)); await tx.CommitAsync(); return Results.Ok(new { deleted = true }); }
    await Exec(cn, "UPDATE PRODUCT SET Status=0 WHERE ProductID=@id", tx, ("@id", id)); await tx.CommitAsync(); return Results.Ok(new { deleted = false, message = "Sản phẩm đã phát sinh phiếu nhập nên được ẩn." });
}).WithSummary("Xóa sản phẩm chưa có giao dịch; nếu đã phát sinh thì chuyển sang ẩn.");
admin.MapGet("/users", async (int? page, int? pageSize, HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await Paged(db, "SELECT c.CustomerID,c.FullName,c.Gender,c.Email,c.PhoneNumber,c.Address,c.RegistrationDate,a.Username,a.Status FROM CUSTOMER c JOIN ACCOUNT a ON a.AccountID=c.AccountID ORDER BY c.CustomerID DESC", page, pageSize)).WithSummary("Quản trị: xem danh sách khách hàng có phân trang.");
admin.MapPatch("/users/{id:int}/status", async (int id, StatusRequest r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE a SET Status=@s FROM ACCOUNT a JOIN CUSTOMER c ON c.AccountID=a.AccountID WHERE c.CustomerID=@id", null, ("@s", r.Active), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { active = r.Active }); }).WithSummary("Khóa hoặc mở khóa tài khoản khách hàng.");
admin.MapPatch("/users/{id:int}/password", async (int id, PasswordRequest r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); if (r.Password.Length < 8) return Bad("password", "Mật khẩu cần tối thiểu 8 ký tự."); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE a SET PasswordHash=@p FROM ACCOUNT a JOIN CUSTOMER c ON c.AccountID=a.AccountID WHERE c.CustomerID=@id", null, ("@p", Hash(r.Password)), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { message = "Đã khởi tạo mật khẩu." }); }).WithSummary("Quản trị: khởi tạo mật khẩu mới cho khách hàng.");
admin.MapGet("/prices", async (HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT ProductID,ProductCode,ProductName,CostPrice,ProfitRate,SellingPrice FROM PRODUCT ORDER BY ProductName")).WithSummary("Xem giá vốn, tỉ lệ lợi nhuận và giá bán hiện tại.");
admin.MapPatch("/products/{id:int}/profit-rate", async (int id, ProfitRequest r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); if (r.Rate < 0) return Bad("rate", "Tỉ lệ lợi nhuận không được âm."); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE PRODUCT SET ProfitRate=@r WHERE ProductID=@id", null, ("@r", r.Rate), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { message = "Đã cập nhật tỉ lệ lợi nhuận." }); }).WithSummary("Thay đổi tỉ lệ lợi nhuận; giá bán được tính lại tự động.");

admin.MapPost("/receipts", async (ReceiptCreate r, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); if (r.Items.Count == 0 || r.Items.Any(x => x.Quantity <= 0 || x.ImportPrice < 0) || r.Items.Select(x => x.ProductId).Distinct().Count() != r.Items.Count) return Bad("items", "Phiếu cần sản phẩm khác nhau, số lượng > 0 và giá nhập >= 0.");
    await using var cn = await db.OpenAsync(); await using var tx = (SqlTransaction)await cn.BeginTransactionAsync(); var id = await Scalar(cn, "INSERT INTO GOODS_RECEIPT(ImportDate,Note) OUTPUT INSERTED.ReceiptID VALUES(COALESCE(@date,CONVERT(date,GETDATE())),@note)", tx, ("@date", r.Date), ("@note", r.Note));
    foreach (var x in r.Items) await Exec(cn, "INSERT INTO GOODS_RECEIPT_DETAIL(ReceiptID,ProductID,Quantity,ImportPrice) VALUES(@receipt,@product,@qty,@price)", tx, ("@receipt", id), ("@product", x.ProductId), ("@qty", x.Quantity), ("@price", x.ImportPrice)); await tx.CommitAsync(); return Results.Created($"/api/admin/receipts/{id}", new { id, status = "Chưa hoàn thành" });
}).WithSummary("Tạo phiếu nhập nháp gồm nhiều sản phẩm.");
admin.MapGet("/receipts", async (string? status, DateTime? from, DateTime? to, string? q, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); var filters = new List<string>(); var a = new List<(string, object?)>(); if (status != null) { filters.Add("r.Status=@s"); a.Add(("@s", status)); } if (from.HasValue) { filters.Add("r.ImportDate>=@from"); a.Add(("@from", from.Value.Date)); } if (to.HasValue) { filters.Add("r.ImportDate<=@to"); a.Add(("@to", to.Value.Date)); } if (!string.IsNullOrWhiteSpace(q)) { filters.Add("EXISTS(SELECT 1 FROM GOODS_RECEIPT_DETAIL d JOIN PRODUCT p ON p.ProductID=d.ProductID WHERE d.ReceiptID=r.ReceiptID AND p.ProductName LIKE @q)"); a.Add(("@q", "%" + q.Trim() + "%")); }
    await using var cn = await db.OpenAsync(); var rows = await Rows(cn, "SELECT * FROM vw_GoodsReceiptSummary r " + (filters.Count == 0 ? "" : "WHERE " + string.Join(" AND ", filters)) + " ORDER BY ImportDate DESC,ReceiptID DESC", null, a.ToArray()); return Results.Ok(new { items = rows });
}).WithSummary("Tìm phiếu nhập theo trạng thái, khoảng ngày hoặc tên sản phẩm.");
admin.MapGet("/receipts/{id:int}", async (int id, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var receipt = await One(cn, "SELECT * FROM vw_GoodsReceiptSummary WHERE ReceiptID=@id", null, ("@id", id)); if (receipt is null) return Results.NotFound(); receipt["items"] = await Rows(cn, "SELECT d.ProductID,p.ProductName,d.Quantity,d.ImportPrice,d.Amount FROM GOODS_RECEIPT_DETAIL d JOIN PRODUCT p ON p.ProductID=d.ProductID WHERE d.ReceiptID=@id", null, ("@id", id)); return Results.Ok(new { item = receipt }); }).WithSummary("Xem thông tin và các dòng sản phẩm của một phiếu nhập.");
admin.MapPut("/receipts/{id:int}", async (int id, ReceiptUpdate r, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); await using var tx = (SqlTransaction)await cn.BeginTransactionAsync(); var status = Convert.ToString(await Scalar(cn, "SELECT Status FROM GOODS_RECEIPT WHERE ReceiptID=@id", tx, ("@id", id))); if (status != "Chưa hoàn thành") { await tx.RollbackAsync(); return Results.Conflict(new { error = "Phiếu không tồn tại hoặc đã hoàn thành." }); }
    if (r.Date.HasValue || r.Note is not null) await Exec(cn, "UPDATE GOODS_RECEIPT SET ImportDate=COALESCE(@date,ImportDate),Note=COALESCE(@note,Note) WHERE ReceiptID=@id", tx, ("@date", r.Date), ("@note", r.Note), ("@id", id));
    if (r.Items is not null) { await Exec(cn, "DELETE FROM GOODS_RECEIPT_DETAIL WHERE ReceiptID=@id", tx, ("@id", id)); foreach (var x in r.Items) await Exec(cn, "INSERT INTO GOODS_RECEIPT_DETAIL(ReceiptID,ProductID,Quantity,ImportPrice) VALUES(@id,@product,@qty,@price)", tx, ("@id", id), ("@product", x.ProductId), ("@qty", x.Quantity), ("@price", x.ImportPrice)); }
    await tx.CommitAsync(); return Results.Ok(new { message = "Đã cập nhật phiếu nhập." });
}).WithSummary("Sửa ngày, ghi chú hoặc sản phẩm khi phiếu nhập chưa hoàn thành.");
admin.MapPost("/receipts/{id:int}/complete", async (int id, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE GOODS_RECEIPT SET Status=N'Đã hoàn thành' WHERE ReceiptID=@id AND Status=N'Chưa hoàn thành'", null, ("@id", id)); return n == 0 ? Results.Conflict(new { error = "Không tìm thấy phiếu nháp để hoàn tất." }) : Results.Ok(new { id, status = "Đã hoàn thành" });
}).WithSummary("Hoàn thành phiếu nhập; cập nhật tồn kho và giá vốn bình quân.");
admin.MapGet("/price-history", async (int? productId, int? receiptId, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); var sql = "SELECT r.ReceiptID,d.ProductID,p.ProductName,d.ImportPrice,p.ProfitRate,p.SellingPrice,r.ImportDate FROM GOODS_RECEIPT_DETAIL d JOIN GOODS_RECEIPT r ON r.ReceiptID=d.ReceiptID JOIN PRODUCT p ON p.ProductID=d.ProductID WHERE r.Status=N'Đã hoàn thành'"; var a = new List<(string, object?)>(); if (productId.HasValue) { sql += " AND p.ProductID=@p"; a.Add(("@p", productId)); } if (receiptId.HasValue) { sql += " AND r.ReceiptID=@r"; a.Add(("@r", receiptId)); } sql += " ORDER BY r.ImportDate DESC,r.ReceiptID DESC"; return await List(db, sql, a.ToArray());
}).WithSummary("Tra cứu giá nhập và giá bán theo sản phẩm hoặc phiếu nhập.");

app.MapGet("/api/cart", async (HttpContext c, ShopDb db) => !IsCustomer(c) ? AuthFail(c) : await List(db, "SELECT ci.ProductID productId,p.ProductName name,p.Unit unit,p.Image image,ci.Quantity quantity,p.StockQuantity stock,p.SellingPrice unitPrice,ci.Quantity*p.SellingPrice lineTotal FROM SHOPPING_CART_ITEM ci JOIN PRODUCT p ON p.ProductID=ci.ProductID WHERE ci.CustomerID=@customer AND p.Status=1", ("@customer", CustomerId(c)))).WithTags("Giỏ hàng").WithSummary("Khách hàng xem các mặt hàng trong giỏ và tổng giá tạm tính.");
app.MapPost("/api/cart/items", async (OrderLine r, HttpContext c, ShopDb db) =>
{
    if (!IsCustomer(c)) return AuthFail(c); if (r.ProductId <= 0 || r.Quantity <= 0) return Bad("quantity", "Số lượng phải lớn hơn 0."); await using var cn = await db.OpenAsync();
    var p = await One(cn, "SELECT StockQuantity FROM PRODUCT WHERE ProductID=@id AND Status=1", null, ("@id", r.ProductId)); if (p is null) return Results.NotFound();
    var old = Convert.ToInt32(await Scalar(cn, "SELECT Quantity FROM SHOPPING_CART_ITEM WHERE CustomerID=@c AND ProductID=@p", null, ("@c", CustomerId(c)), ("@p", r.ProductId)) ?? 0); var total = old + r.Quantity; if (total > Convert.ToInt32(p["StockQuantity"])) return Results.Conflict(new { error = "Số lượng vượt tồn kho." });
    await Exec(cn, "IF EXISTS(SELECT 1 FROM SHOPPING_CART_ITEM WHERE CustomerID=@c AND ProductID=@p) UPDATE SHOPPING_CART_ITEM SET Quantity=@q WHERE CustomerID=@c AND ProductID=@p ELSE INSERT INTO SHOPPING_CART_ITEM(CustomerID,ProductID,Quantity) VALUES(@c,@p,@q)", null, ("@c", CustomerId(c)), ("@p", r.ProductId), ("@q", total)); return Results.Ok(new { productId = r.ProductId, quantity = total });
}).WithTags("Giỏ hàng").WithSummary("Thêm sản phẩm vào giỏ hoặc cộng thêm vào số lượng hiện có.");
app.MapPut("/api/cart/items/{id:int}", async (int id, OrderLine r, HttpContext c, ShopDb db) =>
{
    if (!IsCustomer(c)) return AuthFail(c); if (r.Quantity <= 0) return Bad("quantity", "Số lượng phải lớn hơn 0."); await using var cn = await db.OpenAsync(); var stock = await Scalar(cn, "SELECT StockQuantity FROM PRODUCT WHERE ProductID=@id AND Status=1", null, ("@id", id)); if (stock is null) return Results.NotFound(); if (r.Quantity > Convert.ToInt32(stock)) return Results.Conflict(new { error = "Số lượng vượt tồn kho." }); var n = await Exec(cn, "UPDATE SHOPPING_CART_ITEM SET Quantity=@q WHERE CustomerID=@c AND ProductID=@p", null, ("@q", r.Quantity), ("@c", CustomerId(c)), ("@p", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { productId = id, quantity = r.Quantity });
}).WithTags("Giỏ hàng").WithSummary("Sửa số lượng một sản phẩm trong giỏ.");
app.MapDelete("/api/cart/items/{id:int}", async (int id, HttpContext c, ShopDb db) => { if (!IsCustomer(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); await Exec(cn, "DELETE FROM SHOPPING_CART_ITEM WHERE CustomerID=@c AND ProductID=@p", null, ("@c", CustomerId(c)), ("@p", id)); return Results.Ok(new { message = "Đã xóa sản phẩm khỏi giỏ." }); }).WithTags("Giỏ hàng").WithSummary("Xóa mặt hàng khỏi giỏ hàng.");

app.MapPost("/api/orders", async (OrderCreate r, HttpContext c, ShopDb db) =>
{
    if (!IsCustomer(c)) return AuthFail(c); if (r.PaymentMethod is not ("Tiền mặt" or "Chuyển khoản" or "Trực tuyến")) return Bad("paymentMethod", "Chọn Tiền mặt, Chuyển khoản hoặc Trực tuyến.");
    await using var cn = await db.OpenAsync(); await using var tx = (SqlTransaction)await cn.BeginTransactionAsync(); var customer = CustomerId(c); var requested = r.Items ?? (await Rows(cn, "SELECT ProductID,Quantity FROM SHOPPING_CART_ITEM WHERE CustomerID=@c", tx, ("@c", customer))).Select(x => new OrderLine(Convert.ToInt32(x["ProductID"]), Convert.ToInt32(x["Quantity"]))).ToList();
    if (requested.Count == 0 || requested.Any(x => x.ProductId <= 0 || x.Quantity <= 0) || requested.Select(x => x.ProductId).Distinct().Count() != requested.Count) { await tx.RollbackAsync(); return Bad("items", "Giỏ hàng cần ít nhất một sản phẩm; số lượng phải dương và sản phẩm không trùng."); }
    var lines = new List<(int Id, int Qty, decimal Price, decimal Cost)>();
    foreach (var x in requested) { var p = await One(cn, "SELECT ProductID,StockQuantity,CostPrice,SellingPrice FROM PRODUCT WHERE ProductID=@id AND Status=1", tx, ("@id", x.ProductId)); if (p is null || Convert.ToInt32(p["StockQuantity"]) < x.Quantity) { await tx.RollbackAsync(); return Results.Conflict(new { error = "Sản phẩm không tồn tại hoặc tồn kho không đủ." }); } lines.Add((x.ProductId, x.Quantity, Convert.ToDecimal(p["SellingPrice"]), Convert.ToDecimal(p["CostPrice"]))); }
    var address = string.IsNullOrWhiteSpace(r.DeliveryAddress) ? null : r.DeliveryAddress.Trim(); var o = await One(cn, "INSERT INTO SALES_ORDER(CustomerID,DeliveryAddress,OrderStatus) OUTPUT INSERTED.OrderID,INSERTED.DeliveryAddress SELECT CustomerID,COALESCE(@address,Address),N'Mới' FROM CUSTOMER WHERE CustomerID=@customer", tx, ("@customer", customer), ("@address", address)); if (o is null) { await tx.RollbackAsync(); return Results.NotFound(); } var orderId = Convert.ToInt32(o["OrderID"]);
    foreach (var x in lines) await Exec(cn, "INSERT INTO ORDER_DETAIL(OrderID,ProductID,Quantity,UnitPrice,CostPrice) VALUES(@order,@product,@qty,@price,@cost)", tx, ("@order", orderId), ("@product", x.Id), ("@qty", x.Qty), ("@price", x.Price), ("@cost", x.Cost));
    await Exec(cn, "INSERT INTO PAYMENT(OrderID,Method,Status,PaymentDate) VALUES(@order,@method,N'Chưa thanh toán',NULL)", tx, ("@order", orderId), ("@method", r.PaymentMethod));
    var summary = await One(cn, "SELECT TotalPayment FROM vw_OrderSummary WHERE OrderID=@id", tx, ("@id", orderId)); var total = summary!["TotalPayment"]; var savedAddress = o["DeliveryAddress"]; await Exec(cn, "DELETE FROM SHOPPING_CART_ITEM WHERE CustomerID=@c", tx, ("@c", customer)); await tx.CommitAsync(); return Results.Created($"/api/orders/{orderId}", new { orderId, status = "Mới", total, deliveryAddress = savedAddress, paymentMethod = r.PaymentMethod, transferInfo = r.PaymentMethod == "Chuyển khoản" ? new { bankName = Environment.GetEnvironmentVariable("BANK_NAME"), accountName = Environment.GetEnvironmentVariable("BANK_ACCOUNT_NAME"), accountNumber = Environment.GetEnvironmentVariable("BANK_ACCOUNT_NUMBER") } : null, items = lines.Select(x => new { productId = x.Id, quantity = x.Qty, unitPrice = x.Price }) });
}).WithTags("Đơn hàng").WithSummary("Tạo đơn từ giỏ hàng hoặc danh sách items; kho trừ khi chuyển sang Đang xử lý");
app.MapGet("/api/orders", async (HttpContext c, ShopDb db) => !IsCustomer(c) ? AuthFail(c) : await List(db, "SELECT s.OrderID,s.CreatedDate,s.OrderStatus,v.TotalPayment,p.Method,p.Status PaymentStatus FROM SALES_ORDER s JOIN vw_OrderSummary v ON v.OrderID=s.OrderID LEFT JOIN PAYMENT p ON p.OrderID=s.OrderID WHERE s.CustomerID=@customer ORDER BY s.CreatedDate DESC,s.OrderID DESC", ("@customer", CustomerId(c)))).WithTags("Đơn hàng").WithSummary("Khách hàng xem lịch sử đơn hàng, đơn mới nhất đứng trước.");
app.MapGet("/api/orders/{id:int}", async (int id, HttpContext c, ShopDb db) =>
{
    if (!IsCustomer(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var order = await One(cn, "SELECT s.OrderID,s.CreatedDate,s.OrderStatus,v.TotalPayment,p.Method,p.Status PaymentStatus,p.PaymentDate FROM SALES_ORDER s JOIN vw_OrderSummary v ON v.OrderID=s.OrderID LEFT JOIN PAYMENT p ON p.OrderID=s.OrderID WHERE s.OrderID=@id AND s.CustomerID=@customer", null, ("@id", id), ("@customer", CustomerId(c))); if (order is null) return Results.NotFound(); order["items"] = await Rows(cn, "SELECT d.ProductID,p.ProductName,d.Quantity,d.UnitPrice,d.Discount,d.Amount FROM ORDER_DETAIL d JOIN PRODUCT p ON p.ProductID=d.ProductID WHERE d.OrderID=@id", null, ("@id", id)); return Results.Ok(new { item = order });
}).WithTags("Đơn hàng").WithSummary("Khách hàng xem chi tiết đơn hàng do mình đặt.");

admin.MapGet("/orders", async (string? status, DateTime? from, DateTime? to, bool? sortByAddress, HttpContext c, ShopDb db) =>
{
    if (!IsAdmin(c)) return AuthFail(c); var filters = new List<string>(); var a = new List<(string, object?)>(); if (status != null) { filters.Add("s.OrderStatus=@status"); a.Add(("@status", status)); } if (from.HasValue) { filters.Add("s.CreatedDate>=@from"); a.Add(("@from", from.Value.Date)); } if (to.HasValue) { filters.Add("s.CreatedDate<=@to"); a.Add(("@to", to.Value.Date)); } var sql = "SELECT s.OrderID,s.CreatedDate,s.OrderStatus,c.FullName,c.Address,v.TotalPayment,p.Method,p.Status PaymentStatus FROM SALES_ORDER s JOIN CUSTOMER c ON c.CustomerID=s.CustomerID JOIN vw_OrderSummary v ON v.OrderID=s.OrderID LEFT JOIN PAYMENT p ON p.OrderID=s.OrderID " + (filters.Count == 0 ? "" : "WHERE " + string.Join(" AND ", filters)) + (sortByAddress == true ? " ORDER BY c.Address,s.CreatedDate DESC" : " ORDER BY s.CreatedDate DESC,s.OrderID DESC"); return await List(db, sql, a.ToArray());
}).WithSummary("Quản trị: lọc đơn theo trạng thái/ngày và sắp xếp theo địa chỉ nếu cần.");
admin.MapGet("/orders/{id:int}", async (int id, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); await using var cn = await db.OpenAsync(); var o = await One(cn, "SELECT s.*,c.FullName,c.PhoneNumber,c.Address,v.TotalPayment,p.Method,p.Status PaymentStatus,p.PaymentDate FROM SALES_ORDER s JOIN CUSTOMER c ON c.CustomerID=s.CustomerID JOIN vw_OrderSummary v ON v.OrderID=s.OrderID LEFT JOIN PAYMENT p ON p.OrderID=s.OrderID WHERE s.OrderID=@id", null, ("@id", id)); if (o is null) return Results.NotFound(); o["items"] = await Rows(cn, "SELECT d.ProductID,p.ProductName,d.Quantity,d.UnitPrice,d.CostPrice,d.Discount,d.Amount FROM ORDER_DETAIL d JOIN PRODUCT p ON p.ProductID=d.ProductID WHERE d.OrderID=@id", null, ("@id", id)); return Results.Ok(new { item = o }); }).WithSummary("Quản trị: xem thông tin khách hàng, thanh toán và sản phẩm trong đơn.");
admin.MapPatch("/orders/{id:int}/status", async (int id, OrderStatus r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); if (r.Status is not ("Mới" or "Đang xử lý" or "Đã giao" or "Đã hủy")) return Bad("status", "Trạng thái đơn hàng không hợp lệ."); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE SALES_ORDER SET OrderStatus=@s WHERE OrderID=@id", null, ("@s", r.Status), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { id, status = r.Status }); }).WithSummary("Quản trị: chuyển đơn sang Mới, Đang xử lý, Đã giao hoặc Đã hủy.");
admin.MapPatch("/orders/{id:int}/payment", async (int id, PaymentUpdate r, HttpContext c, ShopDb db) => { if (!IsAdmin(c)) return AuthFail(c); if (r.Status is not ("Chưa thanh toán" or "Đã thanh toán")) return Bad("status", "Trạng thái thanh toán không hợp lệ."); await using var cn = await db.OpenAsync(); var n = await Exec(cn, "UPDATE PAYMENT SET Status=@s,PaymentDate=CASE WHEN @s=N'Đã thanh toán' THEN CONVERT(date,GETDATE()) ELSE NULL END WHERE OrderID=@id", null, ("@s", r.Status), ("@id", id)); return n == 0 ? Results.NotFound() : Results.Ok(new { id, status = r.Status }); }).WithSummary("Quản trị: cập nhật trạng thái thanh toán và ngày thanh toán.");
admin.MapGet("/inventory", async (DateTime? asOf, HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT p.ProductID,p.ProductName,p.ProductTypeID,COALESCE((SELECT SUM(d.Quantity) FROM GOODS_RECEIPT_DETAIL d JOIN GOODS_RECEIPT r ON r.ReceiptID=d.ReceiptID WHERE d.ProductID=p.ProductID AND r.Status=N'Đã hoàn thành' AND r.ImportDate<=@date),0) TotalImport,COALESCE((SELECT SUM(d.Quantity) FROM ORDER_DETAIL d JOIN SALES_ORDER s ON s.OrderID=d.OrderID WHERE d.ProductID=p.ProductID AND s.OrderStatus IN (N'Đang xử lý',N'Đã giao') AND s.CreatedDate<=@date),0) TotalExport,COALESCE((SELECT SUM(d.Quantity) FROM GOODS_RECEIPT_DETAIL d JOIN GOODS_RECEIPT r ON r.ReceiptID=d.ReceiptID WHERE d.ProductID=p.ProductID AND r.Status=N'Đã hoàn thành' AND r.ImportDate<=@date),0)-COALESCE((SELECT SUM(d.Quantity) FROM ORDER_DETAIL d JOIN SALES_ORDER s ON s.OrderID=d.OrderID WHERE d.ProductID=p.ProductID AND s.OrderStatus IN (N'Đang xử lý',N'Đã giao') AND s.CreatedDate<=@date),0) StockAtDate FROM PRODUCT p ORDER BY p.ProductName", ("@date", (object?)(asOf?.Date ?? DateTime.Today)))).WithSummary("Tra cứu tổng nhập, xuất và tồn kho đến ngày chỉ định.");
admin.MapGet("/inventory/low-stock", async (int? threshold, HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT ProductID,ProductName,StockQuantity,MinStockLevel FROM PRODUCT WHERE Status=1 AND StockQuantity<=@n ORDER BY StockQuantity,ProductName", ("@n", Math.Max(0, threshold ?? 5)))).WithSummary("Liệt kê sản phẩm sắp hết theo ngưỡng tồn kho.");
admin.MapGet("/inventory/movements", async (DateTime? from, DateTime? to, HttpContext c, ShopDb db) => !IsAdmin(c) ? AuthFail(c) : await List(db, "SELECT p.ProductID,p.ProductName,COALESCE(SUM(CASE WHEN r.Status=N'Đã hoàn thành' AND (@from IS NULL OR r.ImportDate>=@from) AND (@to IS NULL OR r.ImportDate<=@to) THEN d.Quantity ELSE 0 END),0) TotalImport,COALESCE((SELECT SUM(od.Quantity) FROM ORDER_DETAIL od JOIN SALES_ORDER s ON s.OrderID=od.OrderID WHERE od.ProductID=p.ProductID AND s.OrderStatus IN (N'Đang xử lý',N'Đã giao') AND (@from IS NULL OR s.CreatedDate>=@from) AND (@to IS NULL OR s.CreatedDate<=@to)),0) TotalExport FROM PRODUCT p LEFT JOIN GOODS_RECEIPT_DETAIL d ON d.ProductID=p.ProductID LEFT JOIN GOODS_RECEIPT r ON r.ReceiptID=d.ReceiptID GROUP BY p.ProductID,p.ProductName ORDER BY p.ProductName", ("@from", from?.Date), ("@to", to?.Date))).WithSummary("Báo cáo tổng nhập và tổng xuất trong khoảng ngày.");
app.Run();

static int AccountId(HttpContext c) => c.Session.GetInt32("accountId") ?? 0;
static async Task<IResult> LoginForRole(Login r, string? requiredRole, HttpContext ctx, ShopDb db)
{
    await using var cn = await db.OpenAsync();
    var u = await One(cn, "SELECT a.AccountID,a.Username,a.PasswordHash,a.Role,a.Status,c.CustomerID,c.FullName FROM ACCOUNT a LEFT JOIN CUSTOMER c ON c.AccountID=a.AccountID WHERE a.Username=@u", null, ("@u", r.Username.Trim()));
    if (u is null || !Verify(r.Password, Convert.ToString(u["PasswordHash"])!)) return Results.Unauthorized();
    if (requiredRole is not null && !string.Equals(Convert.ToString(u["Role"]), requiredRole, StringComparison.Ordinal)) return Results.Forbid();
    if (!Convert.ToBoolean(u["Status"])) return Results.Problem("Tài khoản đã bị khóa.", statusCode: 403);

    ctx.Session.Clear();
    ctx.Session.SetInt32("accountId", Convert.ToInt32(u["AccountID"]));
    ctx.Session.SetString("role", Convert.ToString(u["Role"])!);
    ctx.Session.SetString("username", Convert.ToString(u["Username"])!);
    if (u["CustomerID"] is not DBNull and not null) ctx.Session.SetInt32("customerId", Convert.ToInt32(u["CustomerID"]));
    ctx.Session.SetString("fullName", Convert.ToString(u["FullName"]) ?? Convert.ToString(u["Username"])!);
    return Results.Ok(new { user = new { accountId = u["AccountID"], customerId = u["CustomerID"] is DBNull ? null : u["CustomerID"], username = u["Username"], fullName = u["FullName"], role = u["Role"] } });
}
static int CustomerId(HttpContext c) => c.Session.GetInt32("customerId") ?? 0;
static bool IsAdmin(HttpContext c) => AccountId(c) > 0 && c.Session.GetString("role") == "QuanTriVien";
static bool IsCustomer(HttpContext c) => CustomerId(c) > 0 && c.Session.GetString("role") == "KhachHang";
static IResult AuthFail(HttpContext c) => AccountId(c) == 0 ? Results.Unauthorized() : Results.Forbid();
static IResult Bad(string key, string message) => Results.ValidationProblem(new Dictionary<string, string[]> { [key] = [message] });
static object? EmptyToNull(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim();
static string Hash(string password) { var salt = RandomNumberGenerator.GetBytes(16); return "pbkdf2-sha256$600000$" + Convert.ToBase64String(salt) + "$" + Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(password, salt, 600000, HashAlgorithmName.SHA256, 32)); }
static bool Verify(string password, string stored) { var p = stored.Split('$'); if (p.Length != 4 || p[0] != "pbkdf2-sha256" || !int.TryParse(p[1], out var iterations)) return false; try { return CryptographicOperations.FixedTimeEquals(Rfc2898DeriveBytes.Pbkdf2(password, Convert.FromBase64String(p[2]), iterations, HashAlgorithmName.SHA256, 32), Convert.FromBase64String(p[3])); } catch (FormatException) { return false; } }
static SqlCommand Command(SqlConnection cn, string sql, SqlTransaction? tx, params (string Name, object? Value)[] args) { var cmd = new SqlCommand(sql, cn, tx); foreach (var (name, value) in args) cmd.Parameters.AddWithValue(name, value ?? DBNull.Value); return cmd; }
static async Task<object?> Scalar(SqlConnection cn, string sql, SqlTransaction? tx = null, params (string Name, object? Value)[] args) { await using var cmd = Command(cn, sql, tx, args); return await cmd.ExecuteScalarAsync(); }
static async Task<int> Exec(SqlConnection cn, string sql, SqlTransaction? tx = null, params (string Name, object? Value)[] args) { await using var cmd = Command(cn, sql, tx, args); return await cmd.ExecuteNonQueryAsync(); }
static async Task<List<Dictionary<string, object?>>> Rows(SqlConnection cn, string sql, SqlTransaction? tx = null, params (string Name, object? Value)[] args) { await using var cmd = Command(cn, sql, tx, args); await using var rd = await cmd.ExecuteReaderAsync(); var result = new List<Dictionary<string, object?>>(); while (await rd.ReadAsync()) { var row = new Dictionary<string, object?>(); for (var i = 0; i < rd.FieldCount; i++) row[rd.GetName(i)] = await rd.IsDBNullAsync(i) ? null : rd.GetValue(i); result.Add(row); } return result; }
static async Task<Dictionary<string, object?>?> One(SqlConnection cn, string sql, SqlTransaction? tx = null, params (string Name, object? Value)[] args) => (await Rows(cn, sql, tx, args)).FirstOrDefault();
static async Task<IResult> List(ShopDb db, string sql, params (string Name, object? Value)[] args) { await using var cn = await db.OpenAsync(); return Results.Ok(new { items = await Rows(cn, sql, null, args) }); }
static async Task<IResult> Paged(ShopDb db, string sql, int? page, int? size) { var p = Math.Max(1, page ?? 1); var take = Math.Clamp(size ?? 20, 1, 100); await using var cn = await db.OpenAsync(); var rows = await Rows(cn, "SELECT * FROM (" + sql.Replace("ORDER BY c.CustomerID DESC", "") + ") q ORDER BY CustomerID DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY", null, ("@skip", (p - 1) * take), ("@take", take)); var total = Convert.ToInt32(await Scalar(cn, "SELECT COUNT(*) FROM CUSTOMER")); return Results.Ok(new { items = rows, pagination = new { page = p, pageSize = take, totalItems = total } }); }

record Register(string Username, string Password, string FullName, string Phone, string? Email, string? Gender, DateTime? DateOfBirth, string? Address);
record Login(string Username, string Password);
record Profile(string FullName, string Phone, string? Email, string? Address);
record TypeRequest(string Name, string? Description);
record ProductCreate(string Code, string Name, int TypeId, string? Description, string? Color, string Unit, decimal CostPrice, decimal ProfitRate, int Quantity, int MinStockLevel, string? Image, string? SupplierName, bool Status = true);
record ProductUpdate(string? Code, string? Name, int? TypeId, string? Description, string? Color, string? Unit, decimal? CostPrice, decimal? ProfitRate, int? MinStockLevel, string? Image, string? SupplierName, bool ClearImage = false, bool? Status = null);
record StatusRequest(bool Active);
record AdminCustomer(string Username, string Password, string FullName, string? Email, string Phone, string? Gender, DateTime? DateOfBirth, string? Address);
record PasswordRequest(string Password);
record ProfitRequest(decimal Rate);
record ReceiptLine(int ProductId, int Quantity, decimal ImportPrice);
record ReceiptCreate(DateTime? Date, string? Note, List<ReceiptLine> Items);
record ReceiptUpdate(DateTime? Date, string? Note, List<ReceiptLine>? Items);
record OrderLine(int ProductId, int Quantity);
record OrderCreate(string PaymentMethod, List<OrderLine>? Items = null, string? DeliveryAddress = null);
record OrderStatus(string Status);
record PaymentUpdate(string Status);
